import React, { useRef, useEffect, useState } from "react";
import { HERO_LABELS, BRAND } from "./Content";
import { ArrowDownRight, Sparkles, Crown, Gem, Truck } from "lucide-react";

export default function Hero({ onOpenQuote }) {
  const hostRef = useRef(null);
  const [activeLabel, setActiveLabel] = useState(null);
  const [mousePos, setMousePos] = useState({ x: 50, y: 50 });

  useEffect(() => {
    const onMove = (e) => {
      if (!hostRef.current) return;
      const r = hostRef.current.getBoundingClientRect();
      const nx = (e.clientX - r.left) / r.width;
      const ny = (e.clientY - r.top) / r.height;
      setMousePos({ x: nx * 100, y: ny * 100 });

      let best = null;
      let bestDist = Infinity;
      HERO_LABELS.forEach((l) => {
        const dx = l.x - nx * 100;
        const dy = l.y - ny * 100;
        const d = dx * dx + dy * dy;
        if (d < bestDist) { bestDist = d; best = l; }
      });
      if (bestDist < 25 * 25) setActiveLabel(best);
      else setActiveLabel(null);
    };
    const el = hostRef.current;
    if (el) { el.addEventListener("mousemove", onMove); el.addEventListener("mouseleave", () => setActiveLabel(null)); }
    return () => { if (el) { el.removeEventListener("mousemove", onMove); } };
  }, []);

  return (
    <section ref={hostRef} className="relative w-full overflow-hidden" style={{ height: "100vh", minHeight: 800, background: "linear-gradient(135deg, #ffffff 0%, #faf8f5 50%, #f5f0e8 100%)" }}>

      {/* Decorative Elements */}
      <div className="absolute inset-0 overflow-hidden pointer-events-none">
        {/* Gold accent circles */}
        <div className="absolute top-20 left-10 w-64 h-64 rounded-full opacity-10" style={{ background: "radial-gradient(circle, #d4af37 0%, transparent 70%)" }} />
        <div className="absolute bottom-20 right-10 w-96 h-96 rounded-full opacity-10" style={{ background: "radial-gradient(circle, #d4af37 0%, transparent 70%)" }} />

        {/* Gold border accents */}
        <div className="absolute top-0 left-0 w-full h-2" style={{ background: "linear-gradient(90deg, transparent 0%, #d4af37 50%, transparent 100%)" }} />
        <div className="absolute bottom-0 left-0 w-full h-1" style={{ background: "linear-gradient(90deg, transparent 0%, #d4af37 50%, transparent 100%)" }} />

        {/* Mouse follow glow */}
        <div className="absolute inset-0 transition-all duration-300" style={{
          background: `radial-gradient(600px circle at ${mousePos.x}% ${mousePos.y}%, rgba(212,175,55,0.08), transparent 50%)`,
          pointerEvents: "none"
        }} />

        {/* Product hover labels */}
        {HERO_LABELS.map((label) => (
          <div
            key={label.id}
            className="absolute w-32 h-24 rounded-lg border-2 border-dashed transition-all duration-300 pointer-events-none"
            style={{
              left: `${label.x}%`,
              top: `${label.y}%`,
              transform: "translate(-50%, -50%)",
              borderColor: activeLabel?.id === label.id ? "#d4af37" : "rgba(212,175,55,0.2)",
              background: activeLabel?.id === label.id ? "rgba(212,175,55,0.1)" : "transparent",
              opacity: activeLabel?.id === label.id ? 1 : 0.3,
            }}
          />
        ))}
      </div>

      {/* Main Content */}
      <div className="relative z-10 h-full flex flex-col justify-center px-6 md:px-12 lg:px-24">
        <div className="max-w-6xl mx-auto w-full">

          {/* Top Badge */}
          <div className="flex items-center gap-3 mb-8">
            <div className="w-12 h-px" style={{ background: "linear-gradient(90deg, transparent, #d4af37)" }} />
            <span className="text-xs tracking-[0.3em] uppercase" style={{ color: "#b8902a", fontWeight: 500 }}>Ludhiana, Punjab</span>
            <div className="w-12 h-px" style={{ background: "linear-gradient(90deg, #d4af37, transparent)" }} />
          </div>

          {/* Main Title */}
          <h1 className="serif gold-shimmer leading-[0.9] tracking-tight mb-6" style={{ fontSize: "clamp(64px, 12vw, 180px)", fontWeight: 400 }}>
            D SAJAWAT
          </h1>

          {/* Tagline */}
          <div className="flex items-center gap-4 mb-4">
            <Crown size={24} color="#d4af37" />
            <p className="serif text-2xl md:text-4xl" style={{ color: "#1a080a", fontStyle: "italic", fontWeight: 400 }}>
              {BRAND.tagline}
            </p>
          </div>

          {/* Subtitle */}
          <p className="text-base md:text-lg max-w-2xl mb-8" style={{ color: "rgba(26,8,10,0.7)", lineHeight: 1.7 }}>
            Premium fabrics for weddings & events. Trusted by India's top decorators with Pan India delivery.
            From elegant table covers to stunning ceiling drapes - we bring your vision to life.
          </p>

          {/* Features Pills */}
          <div className="flex flex-wrap gap-3 mb-10">
            <div className="flex items-center gap-2 px-4 py-2 rounded-full bg-white shadow-md" style={{ border: "1px solid rgba(212,175,55,0.3)" }}>
              <Gem size={16} color="#d4af37" />
              <span className="text-sm font-medium" style={{ color: "#1a080a" }}>Premium Quality</span>
            </div>
            <div className="flex items-center gap-2 px-4 py-2 rounded-full bg-white shadow-md" style={{ border: "1px solid rgba(212,175,55,0.3)" }}>
              <Truck size={16} color="#d4af37" />
              <span className="text-sm font-medium" style={{ color: "#1a080a" }}>Pan India Delivery</span>
            </div>
            <div className="flex items-center gap-2 px-4 py-2 rounded-full bg-white shadow-md" style={{ border: "1px solid rgba(212,175,55,0.3)" }}>
              <Crown size={16} color="#d4af37" />
              <span className="text-sm font-medium" style={{ color: "#1a080a" }}>Bulk Orders</span>
            </div>
          </div>

          {/* CTA Buttons */}
          <div className="flex flex-wrap gap-4">
            <a href="#collections" className="btn-gold text-lg px-8 py-4">
              <Sparkles size={20} strokeWidth={1.6} />
              Explore Our Collection
            </a>
            <button onClick={onOpenQuote} className="btn-ghost text-lg px-8 py-4" type="button">
              Get a Quote
              <ArrowDownRight size={20} strokeWidth={1.6} />
            </button>
          </div>

        </div>
      </div>

      {/* Bottom Section - Hover Hint */}
      <div className="absolute bottom-8 left-0 right-0 z-10">
        <div className="max-w-6xl mx-auto px-6 md:px-12 lg:px-24 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="w-2 h-2 rounded-full animate-pulse" style={{ background: "#d4af37" }} />
            <span className="text-sm" style={{ color: "rgba(26,8,10,0.6)" }}>Hover over sections to explore products</span>
          </div>
          <div className="flex items-center gap-4">
            <span className="text-xs tracking-widest uppercase" style={{ color: "rgba(26,8,10,0.4)" }}>12+ Years of Craft</span>
            <span className="text-xs" style={{ color: "rgba(26,8,10,0.3)" }}>|</span>
            <span className="text-xs tracking-widest uppercase" style={{ color: "rgba(26,8,10,0.4)" }}>350+ Decorators</span>
          </div>
        </div>
      </div>

      {/* Hover Label Popup */}
      {activeLabel && (
        <div
          className="hero-label"
          style={{
            left: `${activeLabel.x}%`,
            top: `${activeLabel.y}%`,
            transform: "translate(-50%, -50%)",
            zIndex: 50,
          }}
        >
          {activeLabel.title}
        </div>
      )}

    </section>
  );
}
